import FloatingPanel from "@marko-ui/shadcn/ui/floating-panel/floating-panel.marko";
import Button from "@marko-ui/shadcn/ui/button/button.marko";

<FloatingPanel
  minSize={ width: 260, height: 180 }
  maxSize={ width: 560, height: 480 }
  defaultPosition={ x: 380, y: 200 }
  defaultSize={ width: 340, height: 240 }
>
  <@trigger|props|>
    <Button type="button" ...props variant="secondary">Open constrained panel</Button>
  </@trigger>
  <@title>Constrained</@title>
  <p class="text-muted-foreground">
    This panel cannot be resized below 260×180 or above 560×480.
  </p>
</FloatingPanel>
